    ['code' => 'sales-discovery', 'prof' => 'sales-representative', 'type' => 'technical', 'lvl' => [1, 4], 'diff' => 2, 'sec' => 180, 'skills' => ['commercial_acumen', 'customer_orientation'],
        'fr' => ['Comment menez-vous un premier rendez-vous de découverte avec un prospect ?', 'Préparation, questions ouvertes, reformulation, qualification, prochaine étape.',
