            'prepare,open questions,qualification,next step'],
    ],
    ['code' => 'sales-objection', 'prof' => 'sales-representative', 'type' => 'situational', 'lvl' => [1, 4], 'diff' => 3, 'sec' => 180, 'skills' => ['negotiation', 'communication'],
        'fr' => ['Le prospect vous dit : « C\'est trop cher. » Comment répondez-vous ?', 'Accueillir l\'objection, comprendre, valoriser, adapter sans brader.',
